use std::rc::Rc;

fn main() {
    let shared_data = Rc::new(String::from("قاعدة بيانات مشتركة"));
    println!("العداد بعد الإنشاء: {}", Rc::strong_count(&shared_data)); // 1

    let owner2 = Rc::clone(&shared_data);
    println!("العداد بعد المالك الثاني: {}", Rc::strong_count(&shared_data)); // 2

    {
        let owner3 = Rc::clone(&shared_data);
        println!("العداد داخل النطاق: {}", Rc::strong_count(&shared_data)); // 3
    } // owner3 مات هنا!

    println!("العداد بعد خروج المالك الثالث: {}", Rc::strong_count(&shared_data)); // 2
}

use std::sync::Arc;
use std::thread;

fn main() {
    let config = Arc::new(String::from("إعدادات الإنتاج المشتركة"));
    let mut handles = vec![];

    for i in 0..5 {
        let config_clone = Arc::clone(&config);

        let handle = thread::spawn(move || {
            println!("Thread {} يقرأ بأمان: {}", i, config_clone);
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }
}

