fn main() {
    let mut num = 42;

    // 1. إنشاء الـ Raw Pointers مسموح في الكود الآمن العادي (Safe Code):
    let r1 = &num as *const i32;
    let r2 = &mut num as *mut i32;

    // 2. محاولة قراءة أو تعديل القيمة (Dereferencing) تتطلب unsafe:
    unsafe {
        println!("قراءة r1: {}", *r1);

        *r2 = 99; // تعديل مباشر في الذاكرة عبر المؤشر الخام
        println!("قيمة num بعد التعديل عبر r2: {}", *r2);
    }
}

pub struct SafeBuffer {
    ptr: *mut u8,
    len: usize,
}

impl SafeBuffer {
    pub fn new(size: usize) -> Self {
        let layout = std::alloc::Layout::array::<u8>(size).unwrap();
        let ptr = unsafe { std::alloc::alloc(layout) };
        if ptr.is_null() {
            panic!("فشل حجز الذاكرة!");
        }
        Self { ptr, len: size }
    }

    pub fn write_at(&mut self, index: usize, val: u8) -> Result<(), &'static str> {
        if index >= self.len {
            return Err("تجاوز حدود الذاكرة (Index Out of Bounds)!");
        }
        // الكود الداخلي فقط يستخدم unsafe بأمان تام:
        unsafe {
            *self.ptr.add(index) = val;
        }
        Ok(())
    }
}

impl Drop for SafeBuffer {
    fn drop(&mut self) {
        let layout = std::alloc::Layout::array::<u8>(self.len).unwrap();
        unsafe {
            std::alloc::dealloc(self.ptr, layout);
        }
    }
}
